const CARDS = [
  {id:1,emoji:'🕊️',ar:{title:'لا إكراه في الدين',desc:'الإسلام أعلن حرية العقيدة بنص قرآني صريح. هذا المبدأ سبق كل إعلانات حقوق الإنسان بقرون.',quran:'لَا إِكْرَاهَ فِي الدِّينِ قَد تَّبَيَّنَ الرُّشْدُ مِنَ الْغَيِّ',quranRef:'البقرة ٢: ٢٥٦',action:'تعامل اليوم مع الجميع باحترام بغض النظر عن معتقداتهم'},en:{title:'No Compulsion in Religion',desc:'Islam declared freedom of belief through explicit Quranic text. This principle preceded all human rights declarations by centuries.',quran:'There is no compulsion in religion — the right path is distinct from error',quranRef:'Al-Baqarah 2:256',action:'Treat everyone today with respect regardless of their beliefs'},fr:{title:'Pas de Contrainte en Religion',desc:'L\'Islam a declare la liberte de croyance par un texte coranique explicite. Ce principe a precede toutes les declarations des droits de l\'homme de plusieurs siecles.',quran:'Nulle contrainte en religion — le chemin droit se distingue de l\'erreur',quranRef:'Al-Baqarah 2:256',action:'Traitez tout le monde aujourd\'hui avec respect quelles que soient ses croyances'}},
  {id:2,emoji:'🤝',ar:{title:'التعارف لا التصادم',desc:'الله خلق الناس شعوباً وقبائل ليتعارفوا لا ليتصادموا. التنوع البشري حكمة إلهية.',quran:'يَا أَيُّهَا النَّاسُ إِنَّا خَلَقْنَاكُم مِّن ذَكَرٍ وَأُنثَىٰ وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا',quranRef:'الحجرات ٤٩: ١٣',action:'تعرف اليوم على ثقافة مختلفة عن ثقافتك'},en:{title:'Knowing, Not Clashing',desc:'God created people as nations and tribes to know one another, not to clash. Human diversity is divine wisdom.',quran:'O people, We created you from male and female and made you nations and tribes to know one another',quranRef:'Al-Hujurat 49:13',action:'Learn about a different culture today'},fr:{title:'Se Connaitre, Pas Se Heurter',desc:'Dieu a cree les gens en nations et tribus pour qu\'ils se connaissent, pas pour qu\'ils se heurtent. La diversite humaine est une sagesse divine.',quran:'O gens, Nous vous avons crees d\'un male et d\'une femelle et Nous vous avons faits en nations et tribus pour que vous vous connaissiez',quranRef:'Al-Hujurat 49:13',action:'Decouvrez une culture differente aujourd\'hui'}},
  {id:3,emoji:'🏰',ar:{title:'العهدة العمرية',desc:'عندما فتح عمر بن الخطاب القدس أعطى أهلها الأمان على كنائسهم وصلبانهم. نموذج فريد في التسامح.',quran:'لَكُمْ دِينُكُمْ وَلِيَ دِينِ',quranRef:'الكافرون ١٠٩: ٦',action:'اقرأ عن العهدة العمرية وكيف حمت حقوق غير المسلمين'},en:{title:'The Covenant of Umar',desc:'When Umar conquered Jerusalem, he guaranteed safety for churches and crosses. A unique model of tolerance.',quran:'For you is your religion and for me is mine',quranRef:'Al-Kafirun 109:6',action:'Read about the Covenant of Umar and how it protected non-Muslim rights'},fr:{title:'Le Pacte d\'Omar',desc:'Quand Omar a conquis Jerusalem, il a garanti la securite des eglises et des croix. Un modele unique de tolerance.',quran:'A vous votre religion et a moi la mienne',quranRef:'Al-Kafirun 109:6',action:'Lisez sur le pacte d\'Omar et la protection des droits des non-musulmans'}},
  {id:4,emoji:'⚔️',ar:{title:'الحروب الصليبية: السياق',desc:'الحروب الصليبية كانت حروباً سياسية بغطاء ديني. المسلمون دافعوا عن أرضهم ولم يبدأوا بالعدوان.',quran:'أُذِنَ لِلَّذِينَ يُقَاتَلُونَ بِأَنَّهُمْ ظُلِمُوا',quranRef:'الحج ٢٢: ٣٩',action:'ابحث عن الحقائق التاريخية للحروب الصليبية من مصادر محايدة'},en:{title:'The Crusades: Context',desc:'The Crusades were political wars under religious cover. Muslims defended their land and did not initiate aggression.',quran:'Permission is given to those who fight because they have been wronged',quranRef:'Al-Hajj 22:39',action:'Research the historical facts of the Crusades from neutral sources'},fr:{title:'Les Croisades : Le Contexte',desc:'Les Croisades etaient des guerres politiques sous couvert religieux. Les musulmans ont defendu leur terre et n\'ont pas initie l\'agression.',quran:'Permission est donnee a ceux qui combattent car ils ont ete leses',quranRef:'Al-Hajj 22:39',action:'Recherchez les faits historiques des Croisades a partir de sources neutres'}},
  {id:5,emoji:'📜',ar:{title:'حقوق أهل الذمة',desc:'الإسلام كفل لغير المسلمين في الدولة الإسلامية حقوقهم الكاملة في العبادة والتملك والقضاء.',quran:'لَّا يَنْهَاكُمُ اللَّهُ عَنِ الَّذِينَ لَمْ يُقَاتِلُوكُمْ فِي الدِّينِ أَن تَبَرُّوهُمْ وَتُقْسِطُوا إِلَيْهِمْ',quranRef:'الممتحنة ٦٠: ٨',action:'اقرأ عن حقوق أهل الذمة في الحضارة الإسلامية'},en:{title:'Rights of Non-Muslims',desc:'Islam guaranteed non-Muslims in Islamic states their full rights in worship, ownership, and judiciary.',quran:'God does not forbid you from being kind and just to those who do not fight you in religion',quranRef:'Al-Mumtahanah 60:8',action:'Read about the rights of non-Muslims in Islamic civilization'},fr:{title:'Droits des Non-Musulmans',desc:'L\'Islam a garanti aux non-musulmans dans les Etats islamiques leurs pleins droits de culte, de propriete et de justice.',quran:'Dieu ne vous interdit pas d\'etre bons et equitables envers ceux qui ne vous combattent pas en religion',quranRef:'Al-Mumtahanah 60:8',action:'Lisez sur les droits des non-musulmans dans la civilisation islamique'}},
  {id:6,emoji:'🌍',ar:{title:'الأندلس نموذج التعايش',desc:'في الأندلس عاش المسلمون واليهود والمسيحيون معاً في سلام لقرون. كانت منارة للعلم والتسامح.',quran:'وَلَوْ شَاءَ رَبُّكَ لَجَعَلَ النَّاسَ أُمَّةً وَاحِدَةً',quranRef:'هود ١١: ١١٨',action:'تعرف على قصة التعايش في الأندلس'},en:{title:'Al-Andalus: A Model of Coexistence',desc:'In Al-Andalus, Muslims, Jews, and Christians lived together in peace for centuries. It was a beacon of knowledge and tolerance.',quran:'Had your Lord willed, He would have made the people one nation',quranRef:'Hud 11:118',action:'Learn about the story of coexistence in Al-Andalus'},fr:{title:'Al-Andalus : Un Modele de Coexistence',desc:'En Al-Andalus, musulmans, juifs et chretiens ont vecu ensemble en paix pendant des siecles. C\'etait un phare de savoir et de tolerance.',quran:'Si ton Seigneur avait voulu, Il aurait fait des gens une seule communaute',quranRef:'Hud 11:118',action:'Decouvrez l\'histoire de la coexistence en Al-Andalus'}},
  {id:7,emoji:'💬',ar:{title:'الحوار بين الأديان',desc:'القرآن دعا للحوار مع أهل الكتاب والبحث عن القواسم المشتركة بدلاً من التصادم.',quran:'قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَىٰ كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ',quranRef:'آل عمران ٣: ٦٤',action:'ابحث عن قاسم مشترك مع شخص مختلف عنك في المعتقد'},en:{title:'Interfaith Dialogue',desc:'The Quran called for dialogue with the People of the Book and searching for common ground rather than conflict.',quran:'Say: O People of the Book, come to a word common between us and you',quranRef:'Aal Imran 3:64',action:'Find common ground with someone of a different belief today'},fr:{title:'Le Dialogue Interreligieux',desc:'Le Coran a appele au dialogue avec les Gens du Livre et a la recherche d\'un terrain commun plutot que le conflit.',quran:'Dis : O Gens du Livre, venez a une parole commune entre nous et vous',quranRef:'Aal Imran 3:64',action:'Trouvez un terrain commun avec une personne de croyance differente'}},
  {id:8,emoji:'⚖️',ar:{title:'العدل مع المخالف',desc:'القرآن أمر بالعدل حتى مع الأعداء. العدل أقرب للتقوى من التعصب.',quran:'وَلَا يَجْرِمَنَّكُمْ شَنَآنُ قَوْمٍ عَلَىٰ أَلَّا تَعْدِلُوا',quranRef:'المائدة ٥: ٨',action:'كن عادلاً في حكمك على الآخرين اليوم'},en:{title:'Justice with Opponents',desc:'The Quran commanded justice even with enemies. Justice is closer to piety than bigotry.',quran:'And let not the hatred of a people prevent you from being just',quranRef:'Al-Maidah 5:8',action:'Be fair in your judgment of others today'},fr:{title:'La Justice Envers les Opposants',desc:'Le Coran a ordonne la justice meme envers les ennemis. La justice est plus proche de la piete que le fanatisme.',quran:'Et que la haine d\'un peuple ne vous incite pas a etre injustes',quranRef:'Al-Maidah 5:8',action:'Soyez equitable dans votre jugement des autres aujourd\'hui'}},
  {id:9,emoji:'🕌',ar:{title:'حماية دور العبادة',desc:'الإسلام أمر بحماية الكنائس والمعابد والمساجد. تدمير دور العبادة حرام في الإسلام.',quran:'وَلَوْلَا دَفْعُ اللَّهِ النَّاسَ بَعْضَهُم بِبَعْضٍ لَّهُدِّمَتْ صَوَامِعُ وَبِيَعٌ وَصَلَوَاتٌ وَمَسَاجِدُ',quranRef:'الحج ٢٢: ٤٠',action:'تعرف على كيف حمى المسلمون الكنائس عبر التاريخ'},en:{title:'Protecting Houses of Worship',desc:'Islam commanded the protection of churches, temples, and mosques. Destroying places of worship is forbidden in Islam.',quran:'Were it not that God checks people by means of others, monasteries, churches, synagogues, and mosques would have been demolished',quranRef:'Al-Hajj 22:40',action:'Learn how Muslims protected churches throughout history'},fr:{title:'Proteger les Lieux de Culte',desc:'L\'Islam a ordonne la protection des eglises, temples et mosquees. Detruire les lieux de culte est interdit en Islam.',quran:'Si Dieu ne repoussait pas les gens les uns par les autres, les monasteres, eglises, synagogues et mosquees seraient demolis',quranRef:'Al-Hajj 22:40',action:'Decouvrez comment les musulmans ont protege les eglises a travers l\'histoire'}},
  {id:10,emoji:'📖',ar:{title:'احترام الأنبياء جميعاً',desc:'المسلم يؤمن بجميع الأنبياء ويحترمهم. عيسى وموسى عليهما السلام أنبياء معظمون في الإسلام.',quran:'لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ',quranRef:'البقرة ٢: ٢٨٥',action:'اقرأ قصة نبي مشترك بين الأديان الثلاثة'},en:{title:'Respecting All Prophets',desc:'Muslims believe in and respect all prophets. Jesus and Moses are honored prophets in Islam.',quran:'We make no distinction between any of His messengers',quranRef:'Al-Baqarah 2:285',action:'Read about a prophet shared by the three religions'},fr:{title:'Respecter Tous les Prophetes',desc:'Les musulmans croient en tous les prophetes et les respectent. Jesus et Moise sont des prophetes honores en Islam.',quran:'Nous ne faisons pas de distinction entre Ses messagers',quranRef:'Al-Baqarah 2:285',action:'Lisez sur un prophete commun aux trois religions'}},
  {id:11,emoji:'❤️',ar:{title:'البر والإحسان لغير المسلمين',desc:'البر والإحسان واجبان مع جميع الناس بغض النظر عن الدين. حسن الجوار لا يتوقف على المعتقد.',quran:'وَأَحْسِنُوا إِنَّ اللَّهَ يُحِبُّ الْمُحْسِنِينَ',quranRef:'البقرة ٢: ١٩٥',action:'أحسن اليوم إلى جارك مهما كان دينه'},en:{title:'Kindness to Non-Muslims',desc:'Kindness and goodness are obligatory toward all people regardless of religion. Good neighborliness is not contingent on belief.',quran:'And do good — indeed God loves those who do good',quranRef:'Al-Baqarah 2:195',action:'Be kind to your neighbor today regardless of their religion'},fr:{title:'La Bonte Envers les Non-Musulmans',desc:'La bonte et la bienfaisance sont obligatoires envers tous les gens quel que soit leur religion. Le bon voisinage ne depend pas de la croyance.',quran:'Et faites le bien — Dieu aime ceux qui font le bien',quranRef:'Al-Baqarah 2:195',action:'Soyez bon envers votre voisin aujourd\'hui quel que soit sa religion'}},
  {id:12,emoji:'🌙',ar:{title:'مريم في القرآن',desc:'القرآن خصص سورة كاملة باسم مريم عليها السلام وأثنى عليها ثناءً عظيماً. هذا دليل احترام.',quran:'إِنَّ اللَّهَ اصْطَفَاكِ وَطَهَّرَكِ وَاصْطَفَاكِ عَلَىٰ نِسَاءِ الْعَالَمِينَ',quranRef:'آل عمران ٣: ٤٢',action:'اقرأ سورة مريم وتأمل التكريم القرآني لها'},en:{title:'Mary in the Quran',desc:'The Quran dedicated an entire chapter to Mary and praised her greatly. This demonstrates deep respect.',quran:'God has chosen you and purified you and chosen you above the women of all worlds',quranRef:'Aal Imran 3:42',action:'Read Surah Maryam and reflect on the Quranic honoring of her'},fr:{title:'Marie dans le Coran',desc:'Le Coran a consacre un chapitre entier a Marie et l\'a grandement louee. Cela demontre un profond respect.',quran:'Dieu t\'a choisie, purifiee, et choisie au-dessus des femmes de tous les mondes',quranRef:'Aal Imran 3:42',action:'Lisez la sourate Maryam et reflechissez a l\'honneur coranique qui lui est fait'}},
  {id:13,emoji:'🏗️',ar:{title:'تعصب محاكم التفتيش',desc:'محاكم التفتيش في أوروبا أحرقت الآلاف بتهمة الهرطقة. هذا التعصب لم يعرفه التاريخ الإسلامي.',quran:'مَن قَتَلَ نَفْسًا بِغَيْرِ نَفْسٍ فَكَأَنَّمَا قَتَلَ النَّاسَ جَمِيعًا',quranRef:'المائدة ٥: ٣٢',action:'قارن بين تسامح الإسلام وتعصب محاكم التفتيش'},en:{title:'Inquisition Fanaticism',desc:'The Inquisition in Europe burned thousands on charges of heresy. This fanaticism was unknown in Islamic history.',quran:'Whoever kills a soul not in retaliation it is as if they killed all people',quranRef:'Al-Maidah 5:32',action:'Compare Islamic tolerance with the fanaticism of the Inquisition'},fr:{title:'Le Fanatisme de l\'Inquisition',desc:'L\'Inquisition en Europe a brule des milliers de personnes pour heresie. Ce fanatisme etait inconnu dans l\'histoire islamique.',quran:'Quiconque tue une ame sans raison c\'est comme s\'il avait tue l\'humanite entiere',quranRef:'Al-Maidah 5:32',action:'Comparez la tolerance islamique avec le fanatisme de l\'Inquisition'}},
  {id:14,emoji:'🌟',ar:{title:'صلاح الدين والتسامح',desc:'صلاح الدين الأيوبي عندما استعاد القدس لم ينتقم بل عامل المسيحيين بكرم ورحمة.',quran:'وَإِن جَنَحُوا لِلسَّلْمِ فَاجْنَحْ لَهَا',quranRef:'الأنفال ٨: ٦١',action:'اقرأ عن تسامح صلاح الدين عند فتح القدس'},en:{title:'Saladin and Tolerance',desc:'When Saladin recaptured Jerusalem, he did not seek revenge but treated Christians with generosity and mercy.',quran:'And if they incline to peace, then incline to it',quranRef:'Al-Anfal 8:61',action:'Read about Saladin\'s tolerance when he recaptured Jerusalem'},fr:{title:'Saladin et la Tolerance',desc:'Quand Saladin a repris Jerusalem, il n\'a pas cherche la vengeance mais a traite les chretiens avec generosite et misericorde.',quran:'Et s\'ils inclinent vers la paix, incline vers elle aussi',quranRef:'Al-Anfal 8:61',action:'Lisez sur la tolerance de Saladin lors de la reprise de Jerusalem'}},
  {id:15,emoji:'📊',ar:{title:'مقارنة منصفة',desc:'الغزالي يدعو لمقارنة منصفة بين تاريخ المسيحية والإسلام في التعامل مع الآخر.',quran:'يَا أَيُّهَا الَّذِينَ آمَنُوا كُونُوا قَوَّامِينَ بِالْقِسْطِ',quranRef:'النساء ٤: ١٣٥',action:'ابحث بإنصاف عن نماذج التسامح في كلا الدينين'},en:{title:'A Fair Comparison',desc:'Al-Ghazali calls for a fair comparison between the histories of Christianity and Islam in dealing with the other.',quran:'O believers, be persistently standing firm in justice',quranRef:'An-Nisa 4:135',action:'Research fairly models of tolerance in both religions'},fr:{title:'Une Comparaison Equitable',desc:'Al-Ghazali appelle a une comparaison equitable entre les histoires du christianisme et de l\'Islam dans le traitement de l\'autre.',quran:'O croyants, soyez fermement attaches a la justice',quranRef:'An-Nisa 4:135',action:'Recherchez equitablement des modeles de tolerance dans les deux religions'}},
  {id:16,emoji:'🌱',ar:{title:'التسامح ثمرة الإيمان',desc:'التسامح الحقيقي ينبع من الإيمان لا من الضعف. المؤمن القوي يتسامح لأنه واثق بربه.',quran:'وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنْ عَزْمِ الْأُمُورِ',quranRef:'الشورى ٤٢: ٤٣',action:'سامح اليوم شخصاً أساء إليك'},en:{title:'Tolerance: Fruit of Faith',desc:'True tolerance springs from faith, not from weakness. The strong believer is tolerant because they trust in God.',quran:'And whoever is patient and forgives, that is truly of the matters requiring resolve',quranRef:'Ash-Shura 42:43',action:'Forgive someone who wronged you today'},fr:{title:'La Tolerance : Fruit de la Foi',desc:'La vraie tolerance nait de la foi, pas de la faiblesse. Le croyant fort est tolerant parce qu\'il a confiance en Dieu.',quran:'Et quiconque est patient et pardonne, c\'est la une marque de caractere',quranRef:'Ash-Shura 42:43',action:'Pardonnez aujourd\'hui a quelqu\'un qui vous a fait du tort'}},
  {id:17,emoji:'🔑',ar:{title:'الحرية الدينية في القرآن',desc:'القرآن يؤكد أن الهداية بيد الله وليست بالإكراه. على الداعية البلاغ فقط.',quran:'لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ',quranRef:'الغاشية ٨٨: ٢٢',action:'احترم حرية اختيار الآخرين حتى لو اختلفت معهم'},en:{title:'Religious Freedom in the Quran',desc:'The Quran affirms that guidance is in God\'s hands, not through coercion. The caller\'s duty is only to convey.',quran:'You are not a controller over them',quranRef:'Al-Ghashiyah 88:22',action:'Respect others\' freedom of choice even if you disagree'},fr:{title:'La Liberte Religieuse dans le Coran',desc:'Le Coran affirme que la guidance est entre les mains de Dieu, pas par la coercition. Le devoir du predicateur est seulement de transmettre.',quran:'Tu n\'es pas un dominateur sur eux',quranRef:'Al-Ghashiyah 88:22',action:'Respectez la liberte de choix des autres meme si vous n\'etes pas d\'accord'}},
  {id:18,emoji:'📚',ar:{title:'علماء مسلمون ويهود ومسيحيون',desc:'في العصر الذهبي الإسلامي تعاون العلماء من مختلف الأديان في ترجمة العلوم وتطويرها.',quran:'وَجَعَلْنَاكُمْ شُعُوبًا وَقَبَائِلَ لِتَعَارَفُوا',quranRef:'الحجرات ٤٩: ١٣',action:'ابحث عن مثال للتعاون العلمي بين أديان مختلفة'},en:{title:'Muslim, Jewish, and Christian Scholars',desc:'In the Islamic Golden Age, scholars from different religions collaborated in translating and advancing sciences.',quran:'And We made you nations and tribes to know one another',quranRef:'Al-Hujurat 49:13',action:'Research an example of scientific collaboration between different faiths'},fr:{title:'Savants Musulmans, Juifs et Chretiens',desc:'A l\'age d\'or islamique, des savants de differentes religions ont collabore pour traduire et faire avancer les sciences.',quran:'Et Nous avons fait de vous des nations et des tribus pour que vous vous connaissiez',quranRef:'Al-Hujurat 49:13',action:'Recherchez un exemple de collaboration scientifique entre differentes religions'}},
  {id:19,emoji:'🤲',ar:{title:'الدعاء للآخرين',desc:'النبي كان يدعو لهداية غير المسلمين لا لهلاكهم. الداعية يحب الخير لجميع البشر.',quran:'فَقُولَا لَهُ قَوْلًا لَّيِّنًا لَّعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَىٰ',quranRef:'طه ٢٠: ٤٤',action:'ادعُ اليوم بالخير لشخص من دين مختلف'},en:{title:'Praying for Others',desc:'The Prophet used to pray for the guidance of non-Muslims, not for their destruction. The caller loves good for all humanity.',quran:'Speak to him gently — perhaps he may remember or have fear',quranRef:'Taha 20:44',action:'Pray today for the wellbeing of someone of a different faith'},fr:{title:'Prier pour les Autres',desc:'Le Prophete priait pour la guidance des non-musulmans, pas pour leur destruction. Le predicateur aime le bien pour toute l\'humanite.',quran:'Parlez-lui doucement — peut-etre se souviendra-t-il ou aura-t-il crainte',quranRef:'Taha 20:44',action:'Priez aujourd\'hui pour le bien-etre d\'une personne de foi differente'}},
  {id:20,emoji:'🌈',ar:{title:'التسامح طريق السلام',desc:'التعصب يصنع الحروب والتسامح يصنع السلام. الإسلام يدعو للسلام العالمي المبني على العدل والاحترام.',quran:'يَا أَيُّهَا الَّذِينَ آمَنُوا ادْخُلُوا فِي السِّلْمِ كَافَّةً',quranRef:'البقرة ٢: ٢٠٨',action:'انشر رسالة تسامح وسلام اليوم'},en:{title:'Tolerance: The Path to Peace',desc:'Fanaticism creates wars and tolerance creates peace. Islam calls for global peace built on justice and respect.',quran:'O believers, enter into peace completely',quranRef:'Al-Baqarah 2:208',action:'Spread a message of tolerance and peace today'},fr:{title:'La Tolerance : Le Chemin vers la Paix',desc:'Le fanatisme cree les guerres et la tolerance cree la paix. L\'Islam appelle a la paix mondiale fondee sur la justice et le respect.',quran:'O croyants, entrez dans la paix entierement',quranRef:'Al-Baqarah 2:208',action:'Repandez un message de tolerance et de paix aujourd\'hui'}}
];

