let currentCardIdx = 0;

document.addEventListener('DOMContentLoaded', () => {
  setTheme(theme); setLang(lang); initSplash(); initTabs(); initScrollTop();
  renderHome(); renderCards(); renderTolerance(); renderHabits(); renderQuiz(); renderAbout(); renderHelp(); renderDuas(); initScrollReveal(); initKeyboardNav();
});

function initSplash() { let count = 5; const el = document.getElementById('splashCount'); const featuresEl = document.getElementById('splashFeatures'); if (featuresEl) { featuresEl.innerHTML = T[lang].splashFeatures.map((f, i) => `<div class="splash-feature" style="animation-delay:${0.3 + i * 0.3}s">${f}</div>`).join(''); } const interval = setInterval(() => { count--; if (el) el.textContent = count; if (count <= 0) { dismissSplash(); clearInterval(interval); } }, 1000); }
function dismissSplash() { const s = document.getElementById('splash'); if (s) { s.classList.add('hidden'); setTimeout(() => s.style.display = 'none', 500); } playSound('click'); }

function setLang(l) {
  lang = l; localStorage.setItem('tt-lang', l); const isRTL = l === 'ar'; document.documentElement.lang = l; document.documentElement.dir = isRTL ? 'rtl' : 'ltr'; document.body.dir = isRTL ? 'rtl' : 'ltr';
  document.querySelectorAll('.lang-opt').forEach(b => b.classList.toggle('active', b.dataset.lang === l));
  const t = T[l]; const set = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
  set('appTitle', t.appTitle); set('splashSub', t.splashSub); set('splashHint', t.splashHint);
  set('tabHome', t.tabHome); set('tabCards', t.tabCards); set('tabTolerance', t.tabTolerance);
  set('tabHabits', t.tabHabits); set('tabQuiz', t.tabQuiz); set('tabAbout', t.tabAbout);
  set('cardsTitle', t.cardsTitle); set('cardsDesc', t.cardsDesc); set('toleranceTitle', t.toleranceTitle); set('toleranceDesc', t.toleranceDesc);
  set('habitsTitle', t.habitsTitle); set('habitsDesc', t.habitsDesc); set('quizTitle', t.quizTitle); set('quizDesc', t.quizDesc);
  set('helpTitle', t.helpTitle); set('duaPanelTitle', t.duaPanelTitle); set('habitsReset', t.resetBtn);
  renderHome(); renderCards(); renderTolerance(); renderHabits(); renderQuiz(); renderAbout(); renderHelp(); renderDuas();
  const featuresEl = document.getElementById('splashFeatures'); if (featuresEl) { featuresEl.innerHTML = T[l].splashFeatures.map((f, i) => `<div class="splash-feature" style="animation-delay:${0.3 + i * 0.3}s">${f}</div>`).join(''); }
}

function setTheme(t) { theme = t; document.documentElement.dataset.theme = t; localStorage.setItem('tt-theme', t); const idx = themes.indexOf(t); const el = document.getElementById('themeIcon'); if (el) el.textContent = themeIcons[idx]; }
function cycleTheme() { const idx = (themes.indexOf(theme) + 1) % themes.length; setTheme(themes[idx]); showToast(themeNames[themes[idx]]); playSound('theme'); }
function initTabs() { document.querySelectorAll('.tab').forEach(tab => { tab.addEventListener('click', () => { document.querySelectorAll('.tab').forEach(t => t.classList.remove('active')); document.querySelectorAll('.panel').forEach(p => p.classList.remove('active')); tab.classList.add('active'); const panel = document.getElementById('panel-' + tab.dataset.tab); if (panel) panel.classList.add('active'); window.scrollTo({top: 0, behavior: 'smooth'}); playSound('click'); }); }); }

function renderHome() { const t = T[lang]; const dayIdx = new Date().getDate() % CARDS.length; const c = CARDS[dayIdx]; const cd = c[lang]; document.getElementById('dailyCard').innerHTML = `<div class="daily-label">${t.dailyLabel}</div><div class="daily-title">${cd.title}</div><div class="daily-body">${cd.desc}</div><div class="daily-action" onclick="document.querySelector('[data-tab=cards]').click()">${t.tabCards} &#8594;</div>`; const sections = [{icon:'🕊️',tab:'cards',title:t.tabCards,desc:lang==='ar'?'٢٠ بطاقة تسامح':lang==='fr'?'20 cartes':'20 cards'},{icon:'⚖️',tab:'tolerance',title:t.tabTolerance,desc:lang==='ar'?'نماذج تاريخية':lang==='fr'?'Modeles historiques':'Historical models'},{icon:'📋',tab:'habits',title:t.tabHabits,desc:lang==='ar'?'تتبع يومي':lang==='fr'?'Suivi quotidien':'Daily tracking'},{icon:'🤔',tab:'quiz',title:t.tabQuiz,desc:lang==='ar'?'اختبر نفسك':lang==='fr'?'Testez-vous':'Test yourself'},{icon:'📖',tab:'about',title:t.tabAbout,desc:lang==='ar'?'عن الكتاب':lang==='fr'?'Le livre':'About the book'}]; document.getElementById('homeGrid').innerHTML = sections.map(s => `<div class="home-card" onclick="document.querySelector('[data-tab=${s.tab}]').click()"><span class="hc-icon">${s.icon}</span><div class="hc-title">${s.title}</div><div class="hc-desc">${s.desc}</div></div>`).join(''); }

function renderCards() { const t = T[lang]; const searchBar = `<div class="search-bar"><input type="text" id="cardsSearch" class="search-input" placeholder="${t.searchPlaceholder}" oninput="filterCards(this.value)"><span class="search-icon">🔍</span></div>`; const cards = CARDS.map((c, i) => { const d = c[lang]; return `<div class="principle-card scroll-reveal" id="card-${c.id}" data-search="${d.title.toLowerCase()}"><div class="principle-head" onclick="toggleCard('card-${c.id}')"><span class="principle-num">${c.id}</span><span class="principle-emoji">${c.emoji}</span><span class="principle-title">${d.title}</span><span class="principle-chev">&#9660;</span></div><div class="principle-body"><div class="principle-inner"><p class="principle-desc">${d.desc}</p><div class="verse-box"><div class="verse-arabic">${d.quran}</div><div class="verse-ref">${d.quranRef}</div></div><div class="action-box"><span class="action-icon">💡</span><span>${d.action}</span></div><button class="share-btn" onclick="event.stopPropagation();shareCard(${i})"><span class="share-icon">&#128279;</span> ${t.share}</button></div></div></div>`; }).join(''); document.getElementById('cardsContainer').innerHTML = searchBar + cards; }
function filterCards(query) { const q = query.toLowerCase().trim(); document.querySelectorAll('.principle-card').forEach(card => { const s = card.dataset.search || ''; const t = card.querySelector('.principle-title'); card.style.display = (!q || s.includes(q) || (t && t.textContent.toLowerCase().includes(q))) ? '' : 'none'; }); }
async function shareCard(idx) { const c = CARDS[idx]; const d = c[lang]; const text = `${c.emoji} ${d.title}\n\n${d.desc}\n\n📖 ${d.quran}\n\n💡 ${d.action}\n\n— التعصب والتسامح | Fanaticism & Tolerance`; if (navigator.share) { try { await navigator.share({ title: d.title, text }); } catch(e) {} } else { try { await navigator.clipboard.writeText(text); showToast(lang === 'ar' ? 'تم النسخ!' : lang === 'fr' ? 'Copie !' : 'Copied!'); } catch(e) { showToast('Could not copy'); } } }

function renderTolerance() { document.getElementById('toleranceContainer').innerHTML = TOLERANCE_DATA.map(r => { const d = r[lang]; return `<div class="anxiety-card scroll-reveal"><div class="anxiety-header"><span class="anxiety-emoji">${r.emoji}</span><span class="anxiety-title">${d.title}</span></div><div class="anxiety-problem"><span class="anxiety-label">${lang==='ar'?'❌ التعصب':lang==='fr'?'❌ Le Fanatisme':'❌ Fanaticism'}</span>${d.problem}</div><div class="anxiety-solution"><span class="anxiety-label">${lang==='ar'?'✅ التسامح':lang==='fr'?'✅ La Tolerance':'✅ Tolerance'}</span>${d.solution}</div></div>`; }).join(''); }

function renderHabits() { const today = new Date().toDateString(); let hs = JSON.parse(localStorage.getItem('tt-habits') || '{}'); if (hs.date !== today) { updateStreak(hs); hs = { date: today, done: [] }; localStorage.setItem('tt-habits', JSON.stringify(hs)); } const streak = getStreak(); const streakHTML = streak > 0 ? `<div class="streak-badge">🔥 ${streak} ${T[lang].streakMsg}</div>` : ''; document.getElementById('habitsContainer').innerHTML = HABITS.map((h, i) => { const d = h[lang]; const isDone = hs.done.includes(i); return `<div class="habit-item ${isDone ? 'done' : ''}" onclick="toggleHabit(${i})"><span class="habit-check">${isDone ? '&#10003;' : ''}</span><span class="habit-emoji">${h.emoji}</span><div><div class="habit-label">${d.label}</div><div class="habit-source">${d.source}</div></div></div>`; }).join(''); const streakEl = document.getElementById('streakBadge'); if (streakEl) streakEl.innerHTML = streakHTML; updateHabitsProgress(hs); }
function toggleHabit(i) { const today = new Date().toDateString(); let hs = JSON.parse(localStorage.getItem('tt-habits') || '{}'); if (hs.date !== today) hs = { date: today, done: [] }; const idx = hs.done.indexOf(i); if (idx > -1) hs.done.splice(idx, 1); else hs.done.push(i); localStorage.setItem('tt-habits', JSON.stringify(hs)); renderHabits(); playSound(idx > -1 ? 'click' : 'success'); if (hs.done.length === HABITS.length) { launchConfetti(); showToast(T[lang].allDone); } }
function resetHabits() { localStorage.setItem('tt-habits', JSON.stringify({ date: new Date().toDateString(), done: [] })); renderHabits(); showToast(lang === 'ar' ? 'تم إعادة التعيين' : lang === 'fr' ? 'Reinitialise' : 'Reset'); }
function updateHabitsProgress(hs) { const done = hs.done.length; const total = HABITS.length; const pct = total > 0 ? (done / total * 100) : 0; const fill = document.getElementById('habitsFill'); const txt = document.getElementById('habitsText'); if (fill) fill.style.width = pct + '%'; if (txt) txt.textContent = `${done}/${total}`; }
function updateStreak(prev) { let sd = JSON.parse(localStorage.getItem('tt-streak') || '{"count":0,"lastDate":""}'); if (prev && prev.done && prev.done.length === HABITS.length && prev.date) { const y = new Date(); y.setDate(y.getDate() - 1); if (prev.date === y.toDateString()) sd.count++; else if (prev.date !== new Date().toDateString()) sd.count = prev.done.length === HABITS.length ? 1 : 0; sd.lastDate = prev.date; } else if (prev && prev.date) { sd.count = 0; sd.lastDate = prev.date; } localStorage.setItem('tt-streak', JSON.stringify(sd)); }
function getStreak() { return JSON.parse(localStorage.getItem('tt-streak') || '{"count":0}').count; }
function launchConfetti() { const canvas = document.getElementById('confettiCanvas'); if (!canvas) return; canvas.style.display = 'block'; const ctx = canvas.getContext('2d'); canvas.width = window.innerWidth; canvas.height = window.innerHeight; const particles = []; const colors = ['#6A1B9A','#AB47BC','#CE93D8','#E1BEE7','#66BB6A','#FFA726','#FFD54F']; for (let i = 0; i < 120; i++) particles.push({x:Math.random()*canvas.width,y:Math.random()*canvas.height-canvas.height,w:Math.random()*10+5,h:Math.random()*6+3,color:colors[Math.floor(Math.random()*colors.length)],vx:(Math.random()-.5)*4,vy:Math.random()*3+2,rot:Math.random()*360,rotSpeed:(Math.random()-.5)*10}); let frame = 0; function draw() { ctx.clearRect(0,0,canvas.width,canvas.height); particles.forEach(p => { p.x+=p.vx; p.y+=p.vy; p.rot+=p.rotSpeed; ctx.save(); ctx.translate(p.x,p.y); ctx.rotate(p.rot*Math.PI/180); ctx.fillStyle=p.color; ctx.fillRect(-p.w/2,-p.h/2,p.w,p.h); ctx.restore(); }); frame++; if (frame < 120) requestAnimationFrame(draw); else { ctx.clearRect(0,0,canvas.width,canvas.height); canvas.style.display='none'; } } draw(); }

function renderQuiz() { const t = T[lang]; document.getElementById('quizContainer').innerHTML = QUIZ.map((q, i) => `<div class="quiz-question scroll-reveal" id="quiz-q-${i}"><div class="quiz-q-text">${i+1}. ${q[lang]}</div><div class="quiz-options"><button class="quiz-opt" onclick="selectQuizOpt(${i},2)">${t.yes}</button><button class="quiz-opt" onclick="selectQuizOpt(${i},1)">${t.sometimes}</button><button class="quiz-opt" onclick="selectQuizOpt(${i},0)">${t.no}</button></div></div>`).join('') + `<button class="quiz-submit" onclick="submitQuiz()">${t.submitQuiz}</button>`; document.getElementById('quizResult').classList.add('hidden'); window._quizAnswers = {}; }
function selectQuizOpt(qi, val) { window._quizAnswers[qi] = val; document.querySelectorAll(`#quiz-q-${qi} .quiz-opt`).forEach((o, oi) => { o.classList.toggle('selected', [2,1,0][oi] === val); }); playSound('click'); }
function submitQuiz() { const answers = window._quizAnswers || {}; if (Object.keys(answers).length < QUIZ.length) { showToast(lang === 'ar' ? 'أجب على جميع الأسئلة' : lang === 'fr' ? 'Repondez a toutes les questions' : 'Answer all questions'); return; } const invertedQs = [1, 3]; let score = 0; Object.entries(answers).forEach(([qi, v]) => { score += invertedQs.includes(parseInt(qi)) ? (2 - v) : v; }); const max = QUIZ.length * 2; const pct = Math.round(score / max * 100); let emoji, title, desc; if (pct >= 75) { emoji = '🕊️'; title = lang==='ar'?'متسامح حقيقي!':lang==='fr'?'Vraiment tolerant !':'Truly Tolerant!'; desc = lang==='ar'?'أنت نموذج في التسامح. استمر في نشر السلام!':lang==='fr'?'Vous etes un modele de tolerance. Continuez !':'You are a model of tolerance. Keep spreading peace!'; } else if (pct >= 50) { emoji = '🌱'; title = lang==='ar'?'على الطريق':lang==='fr'?'Sur la bonne voie':'On the Path'; desc = lang==='ar'?'أنت تسير نحو التسامح. واصل القراءة والتطبيق.':lang==='fr'?'Vous allez vers la tolerance. Continuez a lire et pratiquer.':'You\'re moving toward tolerance. Keep reading and practicing.'; } else { emoji = '📚'; title = lang==='ar'?'ابدأ رحلة التسامح':lang==='fr'?'Commencez le voyage':'Start the Journey'; desc = lang==='ar'?'التسامح يحتاج تعلماً وممارسة. ابدأ ببطاقات التسامح.':lang==='fr'?'La tolerance necessite apprentissage et pratique. Commencez par les cartes.':'Tolerance needs learning and practice. Start with the tolerance cards.'; } const result = document.getElementById('quizResult'); result.classList.remove('hidden'); result.innerHTML = `<div class="qr-emoji">${emoji}</div><div class="qr-score">${pct}%</div><div class="qr-title">${title}</div><div class="qr-desc">${desc}</div><button class="quiz-submit" onclick="renderQuiz()" style="margin-top:16px">${T[lang].quizAgain}</button>`; result.scrollIntoView({ behavior: 'smooth' }); playSound('success'); }

function renderAbout() { const about = { ar: { disclaimerTitle:'⚠️ تنبيه مهم',disclaimer:'لست عالماً ولا مفتياً. هذا جهد متواضع من مسلم يحب كتب الشيخ الغزالي. ليست فتوى.',authorName:'الشيخ محمد الغزالي',authorDates:'١٩١٧ — ١٩٩٦',authorBio:'عالم ومفكر إسلامي مصري. ألّف أكثر من ٩٤ كتاباً. عُرف بالتجديد والاعتدال والدفاع عن الإسلام.',bookTitle:'عن الكتاب',bookDesc:'"التعصب والتسامح بين المسيحية والإسلام" كتاب يقارن فيه الشيخ الغزالي بين تعامل المسيحية والإسلام مع الآخر عبر التاريخ، مستشهداً بنماذج تاريخية موثقة في التسامح والتعصب.',sourcesTitle:'المصادر',sources:['كتاب "التعصب والتسامح" — الشيخ محمد الغزالي','القرآن الكريم','صحيح البخاري ومسلم'],contact:'تواصل: abdelhak.bourdim@gmail.com'}, en: { disclaimerTitle:'⚠️ Important Notice',disclaimer:'I am not a scholar or mufti. This is a humble effort. Not a fatwa.',authorName:'Sheikh Mohammed al-Ghazali',authorDates:'1917 — 1996',authorBio:'Egyptian Islamic scholar and thinker. Author of 94+ books. Known for renewal, moderation, and defending Islam.',bookTitle:'About the Book',bookDesc:'"Fanaticism and Tolerance Between Christianity and Islam" compares how Christianity and Islam have dealt with the other throughout history, citing documented historical examples of tolerance and fanaticism.',sourcesTitle:'Sources',sources:['"Fanaticism and Tolerance" — Sheikh Mohammed al-Ghazali','The Holy Quran','Sahih al-Bukhari and Muslim'],contact:'Contact: abdelhak.bourdim@gmail.com'}, fr: { disclaimerTitle:'⚠️ Avis Important',disclaimer:'Je ne suis ni savant ni mufti. C\'est un effort humble. Pas une fatwa.',authorName:'Sheikh Mohammed al-Ghazali',authorDates:'1917 — 1996',authorBio:'Savant et penseur islamique egyptien. Auteur de plus de 94 livres. Connu pour le renouveau et la moderation.',bookTitle:'A Propos du Livre',bookDesc:'« Fanatisme et Tolerance entre Christianisme et Islam » compare comment le christianisme et l\'Islam ont traite l\'autre a travers l\'histoire, citant des exemples historiques documentes.',sourcesTitle:'Sources',sources:['« Fanatisme et Tolerance » — Sheikh Mohammed al-Ghazali','Le Saint Coran','Sahih al-Bukhari et Muslim'],contact:'Contact : abdelhak.bourdim@gmail.com'} }; const a = about[lang]; document.getElementById('aboutContainer').innerHTML = `<div class="about-disclaimer"><div class="about-disclaimer-title">${a.disclaimerTitle}</div><p>${a.disclaimer}</p></div><div class="about-author"><span class="about-author-icon">📚</span><div class="about-author-info"><div class="about-author-name">${a.authorName}</div><div class="about-author-dates">${a.authorDates}</div><div class="about-author-bio">${a.authorBio}</div></div></div><div class="about-section"><div class="about-section-title">${a.bookTitle}</div><p class="about-text">${a.bookDesc}</p></div><div class="about-section"><div class="about-section-title">${a.sourcesTitle}</div>${a.sources.map(s => `<p class="about-text">&#8226; ${s}</p>`).join('')}</div><div class="about-section"><p class="about-text">${a.contact}</p></div>`; }

function renderHelp() { const help = { ar: [{title:'⚠️ تنبيه',body:'لست عالماً. هذا جهد متواضع لنشر حكمة الشيخ الغزالي.'},{title:'📚 المصادر',body:'كتاب "التعصب والتسامح"، القرآن الكريم، السنة.'},{title:'✨ المميزات',body:'ثلاث لغات، ٣ أنماط، ٢٠ بطاقة، ٨ نماذج تاريخية، تتبع العادات، اختبار، ٨ أدعية.'}], en: [{title:'⚠️ Disclaimer',body:'I am not a scholar. This is a humble effort.'},{title:'📚 Sources',body:'"Fanaticism and Tolerance" by Sheikh al-Ghazali, Quran, Sunnah.'},{title:'✨ Features',body:'Three languages, 3 themes, 20 cards, 8 historical models, habit tracker, quiz, 8 duas.'}], fr: [{title:'⚠️ Avertissement',body:'Je ne suis pas un savant. C\'est un effort humble.'},{title:'📚 Sources',body:'« Fanatisme et Tolerance » par Sheikh al-Ghazali, Coran, Sunnah.'},{title:'✨ Fonctionnalites',body:'Trois langues, 3 themes, 20 cartes, 8 modeles, suivi habitudes, quiz, 8 duas.'}] }; document.getElementById('helpBody').innerHTML = help[lang].map(h => `<div class="help-item"><div class="help-item-title">${h.title}</div><div>${h.body}</div></div>`).join(''); }
function renderDuas() { document.getElementById('duaPanelContent').innerHTML = DUAS.map(d => { const dd = d[lang]; return `<div class="dua-item"><div class="dua-item-label">${dd.label}</div><div class="dua-item-ar">${dd.text}</div><div class="dua-item-tr">${dd.tr}</div></div>`; }).join(''); }
function initScrollReveal() { if (!('IntersectionObserver' in window)) return; const observer = new IntersectionObserver((entries) => { entries.forEach(entry => { if (entry.isIntersecting) { entry.target.classList.add('revealed'); observer.unobserve(entry.target); } }); }, { threshold: 0.08, rootMargin: '0px 0px -40px 0px' }); function observeAll() { document.querySelectorAll('.scroll-reveal:not(.revealed)').forEach(el => observer.observe(el)); } observeAll(); document.querySelectorAll('.tab').forEach(tab => { tab.addEventListener('click', () => setTimeout(observeAll, 100)); }); }
function initKeyboardNav() { document.addEventListener('keydown', (e) => { if (e.key === 'Escape') { const hp = document.getElementById('helpPanel'); if (!hp.classList.contains('hidden')) { toggleHelp(); return; } const dp = document.getElementById('duaPanel'); if (!dp.classList.contains('hidden')) { toggleDuaPanel(); return; } document.querySelectorAll('.principle-card.open').forEach(c => c.classList.remove('open')); } if (e.key === 'ArrowRight' || e.key === 'ArrowLeft') { const panel = document.getElementById('panel-cards'); if (!panel || !panel.classList.contains('active')) return; if (document.activeElement && document.activeElement.id === 'cardsSearch') return; e.preventDefault(); const cards = Array.from(document.querySelectorAll('.principle-card')).filter(c => c.style.display !== 'none'); if (!cards.length) return; if (currentCardIdx >= 0 && currentCardIdx < cards.length) cards[currentCardIdx].classList.remove('open'); const dir = (document.documentElement.dir === 'rtl') ? (e.key === 'ArrowRight' ? -1 : 1) : (e.key === 'ArrowRight' ? 1 : -1); currentCardIdx = Math.max(0, Math.min(cards.length - 1, currentCardIdx + dir)); cards[currentCardIdx].classList.add('open'); cards[currentCardIdx].scrollIntoView({ behavior: 'smooth', block: 'center' }); playSound('click'); } }); }
function toggleCard(id) { const card = document.getElementById(id); if (card) { card.classList.toggle('open'); playSound('click'); } }
function toggleHelp() { document.getElementById('helpPanel').classList.toggle('hidden'); playSound('click'); }
function toggleDuaPanel() { document.getElementById('duaPanel').classList.toggle('hidden'); playSound('click'); }
function showToast(msg) { const t = document.getElementById('toast'); const m = document.getElementById('toastMsg'); if (t && m) { m.textContent = msg; t.style.display = 'block'; setTimeout(() => t.style.display = 'none', 2500); } }
function initScrollTop() { const btn = document.getElementById('scrollTop'); window.addEventListener('scroll', () => { if (btn) btn.classList.toggle('visible', window.scrollY > 300); }); }
const AudioCtx = window.AudioContext || window.webkitAudioContext; let audioCtx;
function playSound(type) { try { if (!audioCtx) audioCtx = new AudioCtx(); const osc = audioCtx.createOscillator(); const gain = audioCtx.createGain(); osc.connect(gain); gain.connect(audioCtx.destination); gain.gain.value = 0.06; if (type === 'click') { osc.frequency.value = 800; osc.type = 'sine'; gain.gain.value = 0.04; } else if (type === 'success') { osc.frequency.value = 523; osc.type = 'sine'; } else if (type === 'theme') { osc.frequency.value = 440; osc.type = 'triangle'; gain.gain.value = 0.05; } osc.start(); osc.stop(audioCtx.currentTime + 0.1); } catch(e) {} }
